import numpy as np, torch, model
torch.manual_seed(1)
net=model.load(); i=2
N=8192
xi=torch.randn(N,2); c=torch.rand(N)
a,S,A=model.decode(net,xi,c,save_states=True,capture=("out_act",))
bad=np.asarray(model.in_basin(i,a)).astype(bool)
F=A['out_act'].numpy()
def fit(lo,hi):
    X=torch.tensor(np.concatenate([F[k] for k in range(lo,hi)])); y=torch.tensor(np.concatenate([bad]*(hi-lo)).astype(np.float32))
    w=torch.zeros(128,requires_grad=True); b=torch.zeros(1,requires_grad=True)
    opt=torch.optim.Adam([w,b],lr=0.05)
    for it in range(800):
        opt.zero_grad(); l=torch.nn.functional.binary_cross_entropy_with_logits(X@w+b,y,pos_weight=torch.tensor(3.)); l.backward(); opt.step()
    return w.detach(),b.item()
dets={}
for lo,hi in [(6,10),(8,12)]:
    dets[(lo,hi)]=fit(lo,hi); np.save(f'det_{lo}_{hi}.npy',dets[(lo,hi)][0].numpy().astype(np.float32)); print(lo,hi,'b',dets[(lo,hi)][1])
torch.manual_seed(2)
M=8192; xi2=torch.randn(M,2); c2=torch.rand(M)
a0=model.decode(net,xi2,c2); bad0=np.asarray(model.in_basin(i,a0)).astype(bool)
def run(w,b,thr,lo,hi,delta):
    x=xi2.clone(); fired=torch.zeros(M,dtype=torch.bool)
    for k in range(20):
        t=torch.full((M,),1-k/20)
        v,aa=net.velocity(x,t,c2,("out_act",),count=False)
        if lo<=k<hi:
            f=(aa['out_act']@w+b)>thr; fired|=f
            v=v+f[:,None].float()*delta
        x=x-v/20
    return x,fired.numpy()
med=0.33
for (lo,hi),(w,b) in dets.items():
  for thr in [0.0,1.0]:
    for J in [5,6,7,0]:
      for mag in [1,2,3]:
        u=torch.tensor([np.cos(J*np.pi/4),np.sin(J*np.pi/4)],dtype=torch.float32)
        delta=-(20/(hi-lo))*mag*med*u
        x,fired=run(w,b,thr,lo,hi,delta)
        badn=np.asarray(model.in_basin(i,x)).astype(bool)
        moved=(np.linalg.norm((x-a0).numpy(),axis=1)>med)
        print(lo,hi,thr,'J',J,'mag',mag,'bad',bad0.mean().round(4),'->',badn.mean().round(4),'fired',fired.mean().round(3),'moved kept',(moved&~bad0).mean().round(4))

import numpy as np, torch, model
net = model.load(); neg=model.negatives()
def dec(xi,c,P=None):
    x=xi.clone(); 
    for k in range(20):
        t=torch.full((x.shape[0],),1-k/20)
        with torch.no_grad(): v=net.velocity(x,t,c,(),count=False)[0]
        if P is not None:
            u,fac,thr,klo,khi,w=P
            s=x@u + fac*t
            fire=(s>fac+thr)&(k>=klo)&(k<khi)
            v=v+fire[:,None].float()*w
        x=x-v/20
    return x
def hist(a):
    ang=np.degrees(np.arctan2(a[:,1],a[:,0]))%360
    return np.histogram(ang,bins=24,range=(0,360))[0]/len(a)
